import { colors, Theme, useTheme } from '@/theme'
import { CheckCircle, CircleAlert, Info, LucideIcon } from 'lucide-react-native'
import { Text, View } from 'react-native'
import { AnythingToastVariant } from '../../../utils/toast'

interface AnythingToastProps {
	variant: AnythingToastVariant
	message: string
	customIcon?: LucideIcon
}

const getBackgroundColor = (theme: Theme, variant: AnythingToastVariant) => {
	switch (variant) {
		case 'success':
			return colors[theme].green[500]
		case 'error':
			return colors[theme].red[500]
		case 'default':
			return colors[theme].gray[900]
		default:
			const exhaustiveCheck: never = variant
			return exhaustiveCheck
	}
}

const getIcon = (variant: AnythingToastVariant, customIcon?: LucideIcon) => {
	if (customIcon) return customIcon
	switch (variant) {
		case 'success':
			return CheckCircle
		case 'error':
			return CircleAlert
		case 'default':
			return Info
		default:
			const exhaustiveCheck: never = variant
			return exhaustiveCheck
	}
}

export const AnythingToast = ({
	variant,
	message,
	customIcon = undefined
}: AnythingToastProps) => {
	const { theme } = useTheme()
	const Icon = getIcon(variant, customIcon)

	return (
		<View
			style={{
				alignSelf: 'center',
				flexDirection: 'row',
				alignItems: 'center',
				gap: 8,
				backgroundColor: getBackgroundColor(theme, variant),
				borderRadius: 28,
				paddingVertical: 10,
				paddingHorizontal: 14
			}}
		>
			<Icon size={18} color={colors[theme].gray[25]} />
			<Text
				style={{
					color: colors[theme].gray[25],
					fontSize: 16,
					fontWeight: '600'
				}}
			>
				{message}
			</Text>
		</View>
	)
}
